53	type RecordedHook =
54	  | 'beforeSession'
55	  | 'beforeUserInput'
56	  | 'afterUserInput'
57	  | 'beforeModelResponse'
58	  | 'afterModelResponse'
59	  | 'afterSession'
60	  | 'onError';
